  "Targets stay where you set them.": "اهداف در جایی که شما تعیین کرده اید باقی می‌مانند.",
  "Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.": "اگر همه تکرارهای همه ست‌ها را کامل کنید، وزنه افزایش می‌یابد. چند بار نرسیدن به هدف باعث کاهش بار تمرین می‌شود.",
  "Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.": "دو ست معمولی و یک ست پایانی تا ناتوانی. اگر در ست آخر از هدف عبور کنید، وزنه افزایش می‌یابد؛ اگر تکرارها دو برابر هدف باشند، افزایش وزنه هم دو برابر می‌شود. یک بار نرسیدن به هدف، وزنه را 10٪ کاهش می‌دهد.",
  "Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.": "با وزنه ثابت در یک بازه تکرار تمرین کنید. وقتی در تمام ست‌ها به سقف بازه رسیدید، وزنه افزایش می‌یابد و تکرارها به حداقل بازه بازمی‌گردند.",
  "Hold every set for the full duration and the target goes up.": "تمام ست‌ها را برای کل مدت‌زمان حفظ کنید تا هدف افزایش یابد.",
  "Nothing logged yet, so this session sets the baseline.": "هنوز تمرینی ثبت نشده است؛ این جلسه مبنای مقایسه قرار می‌گیرد.",
  "Held every set for the full time. Target goes up by {0}s.": "همه ست‌ها را تا پایان زمان نگه داشتید. هدف {0} ثانیه افزایش می‌یابد.",
  "Short {0} sessions in a row. Back off to {1}s and build up again.": "در {0} جلسه پیاپی به زمان هدف نرسیدید. به {1} ثانیه برگردید و دوباره پیشرفت کنید.",
  "Came up short last time. Same target again.": "بار قبل به هدف نرسیدید. هدف همان است.",
  "Top of the rep range in every set. {0} {1} more, back to {2} reps.": "بالای محدوده تکرار در هر ست. {0} {1} بیشتر، بازگشت به {2} تکرار.",
  "Stuck for {0} sessions. Deload to {1} {2}.": "در {0} جلسه پیشرفت نکردید. وزنه را به {1} {2} کاهش دهید.",
  "Same weight, aim for {0} reps this time.": "وزن یکسان، این بار {0} تکرار را هدف بگیرید.",
  "Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.": "ست آخر {0} تکرار بود؛ دو برابر هدف! وزنه را به اندازه {1} {2} افزایش دهید که دو برابر گام معمول است.",
  "Every rep last time. {0} {1} more.": "بار قبل همه تکرارها را کامل کردید. {0} {1} بیشتر.",
  "Missed reps {0} sessions running. Reset to {1} {2} and work back up.": "در {0} جلسه پیاپی به تکرار هدف نرسیدید. وزنه را به {1} {2} کاهش دهید و دوباره پیشرفت کنید.",
  "Missed reps. Reset to {0} {1} and work back up.": "به تکرار هدف نرسیدید. وزنه را به {0} {1} کاهش دهید و دوباره پیشرفت کنید.",
  "Missed reps last time. Same weight again ({0} of {1} to go).": "دفعه قبل تکرارهای از دست رفته. دوباره همان وزن ({0} از {1} باقی مانده است).",
  "Bodyweight: every rep last time, so go for {0} this time.": "وزن بدن: بار قبل همه تکرارها را انجام دادید؛ این بار {0} تکرار را هدف بگیرید.",
  "Bodyweight: same target again until every set is clean.": "وزن بدن: تا وقتی همه ست‌ها کامل و درست انجام شوند، هدف همان است.",
  "{0} sets bring an {1} with them. Switch on Effort per set in Settings to see it.": "{0} ست دارای مقدار {1} است. برای دیدن آن، «شدت هر ست» را در تنظیمات فعال کنید.",
