  "What are RIR and RPE?": "RIR و RPE چیست؟",
  "How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.": "میزان سختی هر ست، در کنار وزنه و تکرارها ثبت می‌شود. دو مقیاس برای یک ارزیابی هستند که از دو جهت شمرده می‌شوند.",
  "How it felt": "چه حسی داشت",
