  "Easy, warm-up territory": "آسان، در حد گرم‌کردن",
  "RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.": "RIR تعداد تکرارهایی است که هنوز توان انجامشان را داشتید؛ RPE همان شدت را روی مقیاس 10 امتیازی نشان می‌دهد، پس RPE ≈ 10 − RIR. هر کدام را که برایتان آشناتر است انتخاب کنید.",
  "The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.": "ردیف مشخص‌شده، محدوده معمول بیشتر ست‌های اصلی است. ست‌های قبلی مقیاس خود را حفظ می‌کنند و این مقدار روی پیشرفت یا 1RM تخمینی تأثیری ندارد.",
