  "Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.": "بیشتر ست‌های اصلی باید نزدیک ناتوانی باشند، نه دقیقاً در ناتوانی. اگر نیمی بسیار آسان و نیمی بسیار سخت باشند، میانگین آن‌ها همچنان مناسب به نظر می‌رسد.",
  "Average effort per workout": "میانگین شدت در هر جلسه",
  "A fuller dot means less left in the tank. The same weight at a lower {0} is progress the line alone doesn’t show.": "نقطه پُرتر یعنی توان کمتری برای ادامه باقی مانده است. انجام همان وزنه با {0} کمتر، پیشرفتی است که خط نمودار به تنهایی نشان نمی‌دهد.",
  "Bodyweight": "وزن بدن",
