  "Ask for a weight on every set.": "در هر ست وزنه بخواهید.",
  "For dips or pull-ups with a belt. Progression then follows the weight.": "برای دیپ یا بارفیکس با کمربند وزنه. پیشرفت بر اساس وزنه تعیین می‌شود.",
