  "Reps climb by one whenever every set was clean. Set a ceiling to add sets instead of reps forever.": "هر زمان که تمام ست‌ها با موفقیت کامل شوند، یک تکرار اضافه می‌شود. برای جلوگیری از افزایش بی‌پایان تکرارها، سقفی تعیین کنید تا به جای آن، ست اضافه شود.",
  "Reps climb to {0}, then a set is added and the reps start over. At {1} sets it asks you to add weight instead.": "تکرارها به {0} می‌رسند، سپس یک ست اضافه می‌شود و تکرارها از نو شروع می‌شوند. در ست‌های {1} از شما می‌خواهد به جای آن وزن اضافه کنید.",
