  "The Coach needs your go-ahead first.": "مربی ابتدا به اجازه شما نیاز دارد.",
  "The key is stored in this phone’s secure storage and never leaves it except to call the provider.": "کلید در حافظه امن این گوشی ذخیره می‌شود و جز برای ارسال درخواست به ارائه‌دهنده سرویس، هرگز از دستگاه خارج نمی‌شود.",
  "This phone calls the provider directly with your key. Every request is charged to your account.": "درخواست‌ها با کلید اختصاصی شما مستقیماً به ارائه‌دهنده ارسال می‌شوند و هزینه هر درخواست از حساب شما کسر می‌شود.",
  "Turn the Coach off on this phone": "مربی را در این تلفن خاموش کنید",
