  "Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.": "سرور شما مربی را با ارائه‌دهنده‌ای که مدیر تنظیم کرده اجرا می‌کند. اطلاعاتی فراتر از داده‌هایی که از قبل همگام می‌شوند، از این گوشی ارسال نمی‌شود.",
  "Loading the exercise catalogue…": "در حال بارگیری کاتالوگ تمرین…",
  "Checking the endpoint…": "در حال بررسی نقطه پایانی…",
  "A local model can take longer.": "یک مدل محلی ممکن است بیشتر طول بکشد.",
  "All optional. The more the Coach knows, the less it guesses.": "همه موارد اختیاری هستند. هرچه اطلاعات مربی بیشتر باشد، حدس و خطا کمتر خواهد بود.",
