  "Building your plan…": "ساختن برنامه شما…",
  "Discarded. Tell me what was off and I will build a different one.": "کنار گذاشته شد. بگویید چه چیزی مناسب نبود تا برنامه دیگری بسازم.",
  "Done! Your plan is back to how it was before my last changes.": "انجام شد! برنامه شما به قبل از آخرین تغییرات من برگشته است.",
  "Edit my answers": "پاسخ‌های من را ویرایش کنید",
  "Experience": "تجربه",
  "Goal, days, equipment, limits": "هدف، روزها، تجهیزات، محدودیت‌ها",
  "Have a look at my training and tell me what you would change.": "نگاهی به تمرینات من بینداز و بگو چه مواردی را تغییر می‌دهی.",
  "Here is what I am working with:": "تجهیزات و شرایط تمرینی من:",
  "Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.": "سلام، من مربی شما هستم. برنامه شما را بر اساس پاسخ‌هایتان می‌سازم و با توجه به تمرینات ثبت‌شده تنظیم می‌کنم. هیچ تغییری بدون تأیید شما اعمال نمی‌شود.",
  "I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.": "من همه چیز را بررسی کردم و چیزی نیست که در حال حاضر تغییر دهم. ادامه بده و بعد از چند جلسه دوباره از من بپرس.",
  "I understand, let’s go": "فهمیدم، بزن بریم",
  "Imported! {0} routines are in your plan and your week is set. See you at the next session.": "وارد شد! {0} روتین به برنامه شما اضافه شد و برنامه هفتگی تنظیم شد. در جلسه بعدی می‌بینمتان.",
  "Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.": "وارد شد! {0} روتین به برنامه شما اضافه شد. برنامه هفتگی تغییری نکرده است؛ هر زمان خواستید آن‌ها را زمان‌بندی کنید.",
  "It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.": "برنامه شما را بر اساس چند پاسخ طراحی می‌کند و با توجه به تمرینات ثبت‌شده تطبیق می‌دهد. هرگز تغییری را بدون تأیید شما اعمال نمی‌کند و تمام تغییرات قابل بازگشت هستند.",
  "Routines, exercises, sets and reps, your weekly schedule and progression settings.": "روتین‌ها، تمرینات، ست‌ها و تکرارها، برنامه هفتگی و تنظیمات پیشرفت شما.",
  "Your logged training": "تمرین ثبت شده شما",
  "Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.": "ست‌های ثبت‌شده در بازه بررسی: وزنه‌ها، تکرارها، زمان‌ها، شدت‌ها، مدت جلسه‌ها و یادداشت‌های جلسه.",
  "Weigh-ins from the same window, and your goal weight if you set one.": "وزن‌کشی‌های همان بازه و وزن هدف شما، اگر آن را تعیین کرده باشید.",
  "What you tell the Coach": "اطلاعات ارائه‌شده به مربی",
  "Your intake answers, including any limitations or injuries you describe.": "پاسخ‌های دریافتی شما، از جمله محدودیت‌ها یا آسیب‌هایی که توضیح می‌دهید.",
  "A few preferences": "چند اولویت",
