  "Imported! {0} routines are in your plan and your rotation starts over with them. See you at the next session.": "وارد شد! {0} روتین به برنامه شما افزوده شد و چرخش تمرین با آن‌ها از سر گرفته می‌شود. در جلسه بعدی می‌بینمتان.",
