  "Nothing yet. Every plan, suggestion and debrief will be kept here, whether you said yes or no.": "هنوز موردی ثبت نشده است. تمام برنامه‌ها، پیشنهادات و بازخوردها (چه پذیرفته و چه رد شده باشند) در اینجا نگهداری می‌شوند.",
