  "That invite code is not valid.": "آن کد دعوت معتبر نیست.",
  "Your current password is not right.": "رمز عبور فعلی شما صحیح نیست.",
  "Your passkey could not be confirmed.": "کلید عبور شما تأیید نشد.",
  "This password is the only way into your profile, so it cannot be removed.": "این گذرواژه تنها راه دسترسی به حساب شماست؛ بنابراین حذف آن امکان‌پذیر نیست.",
  "That reset code is wrong or has expired. Ask your admin for a new one.": "کد بازنشانی اشتباه است یا منقضی شده است. از ادمین خود یک مورد جدید بخواهید.",
