  "1 passkey": "1 کلید عبور",
  "A one-time code lets your phone or another computer sign in with a passkey of its own.": "با یک کد یک‌بارمصرف، گوشی یا رایانه دیگری می‌تواند کلید عبور خودش را بسازد و وارد شود.",
