  "Copy link": "پیوند را کپی کنید",
  "Create a passkey on this device for the profile “{0}”. It signs you in here from now on.": "یک کلید عبور برای حساب «{0}» روی این دستگاه ایجاد کنید تا از این پس برای ورود از آن استفاده شود.",
  "Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.": "هر کلید عبور امکان ورود به این حساب را از دستگاه یا برنامه مدیریت گذرواژه فراهم می‌کند. برای تغییر نام یا حذف، روی آن ضربه بزنید.",
  "Enter the code from your other device.": "کد را از دستگاه دیگر خود وارد کنید.",
  "For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.": "برای این دستگاه، یک کلید امنیتی، یک مدیر رمز عبور یا تلفن شما از طریق کد QR خود مرورگر. ابتدا تأیید کنید که شما هستید.",
  "It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.": "با این کلید عبور دیگر نمی‌توان وارد این حساب شد. دستگاهی که قبلاً با آن وارد شده همچنان متصل می‌ماند. اگر دستگاه گم شده است، از «خروج از همه دستگاه‌ها» استفاده کنید.",
  "It is your only way in, so it cannot be removed until there is another.": "این تنها راه شماست، بنابراین تا زمانی که راه دیگری وجود نداشته باشد نمی‌توان آن را حذف کرد.",
  "Last used {0}": "آخرین استفاده {0}",
  "Make a new code": "یک کد جدید ایجاد کنید",
  "Name, e.g. Work laptop": "نام، مثلاً: لپ‌تاپ کاری",
  "None yet. Add one and sign in without your password.": "هنوز هیچ کدام. یکی اضافه کنید و بدون رمز عبور وارد شوید.",
  "Passkey added": "کلید عبور اضافه شد",
  "Passkey removed": "کلید عبور حذف شد",
  "Passkey {0}": "کلید عبور {0}",
  "Passkeys": "کلیدهای عبور",
  "Remove passkey": "کلید عبور را حذف کنید",
  "Remove this passkey?": "این کلید عبور حذف شود؟",
  "Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.": "این را با دستگاه دیگر اسکن کنید، یا openGym را در آنجا باز کنید و کد را در صفحه ورود به سیستم وارد کنید. یک بار، برای {0} دقیقه کار می‌کند.",
  "That code is wrong, already used or expired. Make a new one on your other device.": "این کد اشتباه است، قبلاً استفاده شده یا منقضی شده است. یک مورد جدید در دستگاه دیگر خود بسازید.",
  "This browser cannot confirm with your passkey. Do this on a device that holds one.": "این مرورگر نمی‌تواند کلید عبور شما را تأیید کند. از دستگاهی استفاده کنید که کلید عبور روی آن ذخیره شده است.",
  "First confirm that it is you.": "ابتدا تأیید کنید که شما هستید.",
  "This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.": "این پروفایل کلید عبور ندارد و این سرور گذرواژه‌ها را نمی‌گیرد، بنابراین هیچ چیز در اینجا نمی‌تواند تأیید کند که شما هستید. از ادمین خود بپرسید",
  "This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.": "این مرورگر نمی‌تواند کلیدهای عبور ایجاد کند، بنابراین نمی‌توان آن را با کد اضافه کرد. پیوند را در مرورگری که می‌تواند باز کنید.",
  "This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.": "این مرورگر با حساب «{0}» وارد شده است. افزودن آن به «{1}»، حساب «{0}» را در اینجا خارج می‌کند.",
  "This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.": "این کد برای پروفایل دیگری است که \"{0}\" نیز نامیده می‌شود، نه پروفایلی که این مرورگر با آن وارد شده است. با افزودن آن به آنجا، شما از اینجا خارج می‌شوید.",
  "Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.": "فقط در صورتی ادامه دهید که این کد از دستگاه خودتان آمده باشد. سپس این مرورگر به \"{0}\" وارد می‌شود، و آنچه در اینجا وارد می‌شوید به آن پروفایل می‌رود.",
  "This code has expired.": "این کد منقضی شده است.",
  "This device already has a passkey for this profile.": "این دستگاه از قبل یک کلید عبور برای این پروفایل دارد.",
  "This passkey already belongs to a profile.": "این کلید عبور از قبل به یک پروفایل تعلق دارد.",
