  "openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.": "openGym دیگر نمی‌تواند روی «{0}» بنویسد، بنابراین کپی‌ها دوباره به Documents/openGym می‌روند. برای برگشت دوباره پوشه را انتخاب کنید.",
  "openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.": "امکان ذخیره‌سازی در پوشه انتخابی وجود ندارد؛ بنابراین فایل‌های پشتیبان در مسیر Documents/openGym ذخیره می‌شوند. برای تغییر، دوباره پوشه را انتخاب کنید.",
  "Nudge me when I skip a planned workout": "اگر تمرین برنامه‌ریزی‌شده را انجام ندادم، یادآوری کن",
  "Nudge tone": "لحن یادآوری",
  "Friendly": "دوستانه",
  "Guilt trip": "احساس گناه",
  "Drill sergeant": "گروهبان سخت‌گیر",
  "One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.": "یک یادآوری در عصر روزی که تمرین برنامه‌ریزی‌شده ثبت نشده است، بین 20:00 و 21:30. پس از 3 روز غیبت پیاپی، تا تمرین بعدی شما یادآوری متوقف می‌شود.",
  "Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.": "در دستگاه دیگری تمرین ثبت کرده‌اید؟ پیش از ارسال یادآوری، هر وقت گوشی اجازه اجرای پس‌زمینه بدهد، برنامه با سرور بررسی می‌کند. باز کردن برنامه همیشه اطلاعات را به‌روز می‌کند.",
  "Everything okay?": "همه چیز خوبه؟",
  "{0} is still waiting. What’s up?": "{0} هنوز منتظره. چه خبر؟",
  "No {0} today? Even a short session tomorrow counts.": "امروز خبری از {0} نیست؟ حتی یه جلسه کوتاه فردا هم ارزش داره.",
  "Rough day? {0} will keep. Tomorrow is a fresh start.": "روز سختی بود؟ {0} منتظر می‌مونه. فردا یه شروع تازه‌ست.",
  "Hey, {0} didn’t happen today. All good?": "امروز {0} انجام نشد. همه چیز خوبه؟",
