  "That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "آن آدرس پاسخ می‌دهد، اما یک صفحه ورود یا قانون پروکسی به جای openGym پاسخ داده است. اجازه دهید /api/ بدون تغییر به openGym برود. به «برنامه تلفن و CORS» در docs/SELF_HOSTING.md مراجعه کنید.",
  "Switch sides": "عوض کردن طرف",
