  "Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.": "پس از اتمام تمرین یا ویرایش یک روتین، یک کپی تاریخ را در پوشه‌ای که انتخاب کرده اید ذخیره می‌کند و جدیدترین {0} را نگه می‌دارد.",
