  "Routines in a loop. Whatever is next stays next until you train it, whatever the day.": "روتین‌ها در یک چرخه تکرار می‌شوند. جلسه بعدی تا وقتی انجامش ندهید، نوبتش باقی می‌ماند؛ روز هفته مهم نیست.",
