  "iPhone doesn’t let openGym vibrate. A sound or a flash does the job.": "آیفون اجازه نمی‌دهد openGym لرزش داشته باشد. صدا یا فلاش کار را انجام می‌دهد.",
  "No account, no cloud. Back it up anytime in Data & backup.": "بدون حساب و فضای ابری. هر زمان خواستید در «داده و پشتیبان» نسخه پشتیبان بگیرید.",
  "Effort per set is off. Turn it on in Settings → Workout to keep rating.": "ثبت شدت هر ست خاموش است. برای ثبت شدت، آن را در تنظیمات ← تمرین فعال کنید.",
  "Enter the code your other device shows under Settings → Account → Add another device. This device then gets a passkey of its own.": "کدی را وارد کنید که در دستگاه دیگر، در تنظیمات ← حساب ← افزودن دستگاه دیگر نمایش داده می‌شود. سپس این دستگاه کلید عبور خودش را می‌گیرد.",
  "Open Settings → Account → “Pair the mobile app” on the openGym site you’re already signed into, then enter its address and the code shown there.": "در سایت openGym که در آن وارد شده‌اید، تنظیمات ← حساب ← «اتصال برنامه تلفن همراه» را باز کنید؛ سپس نشانی سایت و کد نمایش‌داده‌شده را وارد کنید.",
  "Open Settings → Account → “Pair the mobile app” on your openGym site in a browser and enter the new code shown there. What this phone kept is merged into your account.": "در مرورگر، سایت openGym خود را باز کنید و به تنظیمات ← حساب ← «اتصال برنامه تلفن همراه» بروید. کد جدید را وارد کنید. داده‌های نگه‌داشته‌شده در این گوشی با حساب شما ادغام می‌شوند.",
