  "{0} routine was made on this device while signed out. Add it to your profile, or keep the profile exactly as it is on the server.": "روتین {0} در این دستگاه هنگام خروج از سیستم انجام شد. آن را به پروفایل خود اضافه کنید یا پروفایل را دقیقاً همانطور که در سرور است نگه دارید.",
  "{0} routines were made on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "در حالی که از سیستم خارج شده بودید، {0} روتین در این دستگاه انجام شد. آنها را به پروفایل خود اضافه کنید یا پروفایل را دقیقاً همانطور که در سرور است نگه دارید.",
