  "You’ve outgrown the rack: {0} {1} is your heaviest dumbbell, so the weight stays.": "به بالاترین وزنه موجود رسیده‌اید: سنگین‌ترین دمبل شما {0} {1} است، پس وزنه تغییر نمی‌کند.",
