  "Stuck for {0} sessions. Back to {1} {2} of help, start again at {3} sets of {4}.": "در {0} جلسه پیشرفت نکردید. به {1} {2} کمک برگردید و دوباره با {3} ستِ {4} تکراری شروع کنید.",
