  "Your profile, workouts, body weight, photos and videos are deleted from this server for good. There is no undo, and not even your admin can bring them back.": "پروفایل، تمرینات، وزن بدن، عکس‌ها و ویدیوهای شما برای همیشه از این سرور حذف می‌شوند. هیچ واگردی وجود ندارد و حتی ادمین شما هم نمی‌تواند آنها را بازگرداند.",
  "Want a copy first? Export a backup. You can import it into openGym anytime.": "ابتدا یک کپی می‌خواهید؟ یک نسخه پشتیبان خروجی کنید. هر زمان که بخواهید می‌توانید آن را به openGym وارد کنید.",
