  "That is not your account name.": "این نام حساب شما نیست.",
  "You’re the only admin here, and other profiles still use this server. Make someone else an admin first.": "شما تنها سرپرست اینجا هستید و پروفایل‌های دیگر همچنان از این سرور استفاده می‌کنند. ابتدا شخص دیگری را ادمین کنید.",
