  "Sharper animations download once per figure. Until they’re here you see the built-in ones, so nothing ever goes blank.": "انیمیشن های واضح‌تر یک بار در هر شکل دانلود می‌شوند. تا زمانی که آنها اینجا نباشند، موارد داخلی را می‌بینید، بنابراین هیچ چیز خالی نمی‌شود.",
