  "{0} photos know their day and go there. The others go on the day below.": "تاریخ {0} عکس مشخص است و در همان روز ثبت می‌شوند؛ مابقی در روز مشخص‌شده در پایین قرار می‌گیرند.",
  "Every progress photo, lined up by date, for any day. Plus a before/after slider.": "هر عکس پیشرفت، ردیف‌بندی شده بر اساس تاریخ، برای هر روز. به علاوه یک نوار لغزنده قبل و بعد.",
