  "This app can’t confirm with a passkey. Make the code in a browser signed in to this profile, or add a password there first.": "این برنامه نمی‌تواند با کلید عبور تأیید کند. کد را در مرورگری وارد کنید که به این پروفایل وارد شده است، یا ابتدا یک رمز عبور در آنجا اضافه کنید.",
