  "Heart rate during the workout and next to each set, and the workout saved to Apple Health. The watch asks once.": "ضربان قلب در طول تمرین و در کنار هر ست، و تمرین در Apple Health ذخیره شد. ساعت یک بار می‌پرسد.",
