  "Ring": "حلقه",
  "Countdown only": "فقط شمارش معکوس",
  "Your bars": "هالترهای شما",
  "Set the bar once for every exercise of a type.": "برای هر نوع حرکت، وزن هالتر را یک بار تعیین کنید.",
  "Your bar for this type, set in Your bars.": "هالتر شما برای این نوع حرکت، تعیین‌شده در «هالترهای شما».",
  "What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.": "وزن هالترهای باشگاهتان را تعیین کنید. وزن صفحه‌های هر تمرین از وزن هالتر آن محاسبه می‌شود، مگر اینکه برای خود تمرین مقدار دیگری تعیین کرده باشید. وزن‌های ثبت‌شده همچنان مجموع هستند.",
  "Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.": "بیشتر حرکت‌های کتابخانه از «{0}» و برخی از «{1}» استفاده می‌کنند. اگر برای همه از هالتر کوتاه استفاده می‌کنید، هر دو را تنظیم کنید.",
  "Back to the standard bars": "بازگشت به هالترهای استاندارد",
  "Standard bars. Tap if yours are lighter.": "هالترهای استاندارد. اگر هالترهایتان سبک‌ترند روی آن بزنید.",
  "The last warm-up still gets the full rest before your first work set.": "آخرین گرم‌کردن هنوز قبل از اولین ست کاری شما استراحت کامل دارد.",
  "Days per week": "روز در هفته",
  "Hours": "ساعت",
  "h": "ساعت",
  "This device has 1 workout that is not in this backup. Replacing deletes it.": "این دستگاه 1 تمرین دارد که در این نسخه پشتیبان وجود ندارد. جایگزین کردن آن را حذف می‌کند.",
  "This device has {0} workouts that are not in this backup. Replacing deletes them.": "این دستگاه دارای {0} تمرین است که در این نسخه پشتیبان وجود ندارد. جایگزین کردن آنها را حذف می‌کند.",
  "Page {0} of {1}": "صفحه {0} از {1}",
  "Training plan": "برنامه تمرینی",
  "New best": "رکورد جدید",
  "New bests": "رکوردهای جدید",
  "Last 7 days": "7 روز گذشته",
  "Last 4 weeks": "4 هفته گذشته",
  "Last 3 months": "3 ماه گذشته",
  "{0} days": "{0} روز",
  "One weigh-in": "یک وزن‌کشی",
  "No weigh-ins": "بدون وزن‌کشی",
  "Training time": "زمان تمرین",
  "Arrows compare with the {0} days before.": "پیکان‌ها مقایسه با {0} روز قبل را نشان می‌دهند.",
