  'Tell Home Assistant, n8n or ntfy when you finish a workout.': 'وقتی تمرینی را تمام می‌کنید، به Home Assistant، n8n یا ntfy خبر بدهید.',
  'A signed JSON message when a workout is finished, a record falls or you weigh in.': 'یک پیام JSON امضاشده وقتی تمرینی تمام می‌شود، رکوردی شکسته می‌شود یا وزن‌کشی می‌کنید.',
  'Sent by your server, from whichever device you logged on.': 'سرور شما آن را می‌فرستد، از هر دستگاهی که با آن ثبت کرده باشید.',
