  'Back home, practice over. Stats is where the gains pile up. Tap it.': 'برگشتیم خانه، تمرین آزمایشی تمام شد. آمار جایی است که پیشرفت‌ها روی هم جمع می‌شوند. بزنید رویش.',
  'Back it all up': 'از همه چیز پشتیبان بگیرید',
