  'Health apps': 'برنامه‌های سلامت',
  'Here’s the pretend one. Tap it.': 'این همان تمرین آزمایشی است. بزنید رویش.',
  'Home shows it on its day and Start opens it. Change it any time right here.': 'صفحه خانه آن را در روز خودش نشان می‌دهد و «شروع» بازش می‌کند. هر وقت خواستید همین‌جا عوضش کنید.',
  'It starts today’s plan, or lets you pick something else. Tap it for a practice run.': 'برنامه امروز را شروع می‌کند، یا می‌گذارد چیز دیگری انتخاب کنید. برای یک دور آزمایشی بزنید رویش.',
  'Its own page': 'صفحه مخصوص خودش',
  'It’s the first row of the list. Tap it.': 'ردیف اول فهرست است. بزنید رویش.',
  'Log a past workout with its own date and time. It counts like any other.': 'یک تمرین گذشته را با تاریخ و ساعت خودش ثبت کنید. مثل بقیه حساب می‌شود.',
  'Measurements and photos': 'اندازه‌گیری‌ها و عکس‌ها',
  'Missing one? Make it. It works like any other: routines, workouts, records, the body map, backups and sync. Nothing is created until you tap Create.': 'یکی کم است؟ بسازیدش. مثل بقیه کار می‌کند: روتین‌ها، تمرینات، رکوردها، نقشه بدن، پشتیبان‌ها و همگام‌سازی. تا روی «ایجاد» نزنید چیزی ساخته نمی‌شود.',
  'Moving in?': 'دارید اسباب‌کشی می‌کنید؟',
  'Name a routine, add exercises, give it a day': 'روتین را نام‌گذاری کنید، تمرین اضافه کنید، یک روز برایش تعیین کنید',
