  'Name, muscles, equipment and a photo': 'نام، عضلات، تجهیزات و یک عکس',
  'New routines start on the Routines side. Tap Routines.': 'روتین‌های جدید از بخش روتین‌ها شروع می‌شوند. روی «روتین‌ها» بزنید.',
  'Notes': 'یادداشت‌ها',
  'Now give it a day. Tap back to Plan.': 'حالا یک روز برایش تعیین کنید. برگردید به برنامه.',
