  'One more': 'یکی دیگر',
  'Open a check-in to change or delete it. Progress photos work the same way.': 'یک ثبت وزن را باز کنید تا تغییرش دهید یا حذفش کنید. عکس‌های پیشرفت هم همین‌طورند.',
  'Open a workout': 'باز کردن یک تمرین',
  'Optional: your own picture or clip of the setup. Handy for that one weird machine.': 'اختیاری: عکس یا کلیپ خودتان از تنظیم دستگاه. برای آن یک دستگاه عجیب‌غریب خیلی به درد می‌خورد.',
