  'Timed holds start by themselves': 'نگه‌داشتن‌های زمان‌دار خودشان شروع می‌شوند',
  'Waiting till you close that': 'منتظریم آن را ببندید',
  'Up next: {0}, starts by itself': 'بعدی: {0}، خودش شروع می‌شود',
  'When the rest ends: 3, 2, 1 and the hold starts. Pause, restart or stop it any time.': 'وقتی استراحت تمام شود: ۳، ۲، ۱ و نگه‌داشتن شروع می‌شود. هر وقت خواستید مکث، شروع دوباره یا توقفش کنید.',
  'Holds start by themselves': 'نگه‌داشتن‌ها خودشان شروع می‌شوند',
