  'Any blank NTAG sticker works. Writing replaces what was on it.': 'هر برچسب NTAG خالی کار می‌کند. نوشتن، محتوای قبلی آن را جایگزین می‌کند.',
  'Hold the back of your phone to the sticker.': 'پشت گوشی‌تان را به برچسب نزدیک کنید.',
  'Hold the top of your iPhone near the sticker.': 'بالای آیفون خود را نزدیک برچسب نگه دارید.',
  'It isn’t in this workout yet.': 'هنوز در این تمرین نیست.',
  'Just check in': 'فقط ورود به باشگاه',
  'NFC is off. Turn it on in your phone’s settings and try again.': 'NFC خاموش است. آن را در تنظیمات گوشی روشن کنید و دوباره امتحان کنید.',
  'NFC sticker for this exercise': 'برچسب NFC برای این تمرین',
  'Put it on your locker, your bag or the gym door. One tap with your phone and you’re in.': 'آن را روی کمد، کیف یا در باشگاه بچسبانید. یک ضربه با گوشی و وارد شده‌اید.',
  'Set up an NFC sticker': 'راه‌اندازی برچسب NFC',
  'Shows your gym membership code, ready for the scanner.': 'کد عضویت باشگاهتان را آماده برای اسکنر نشان می‌دهد.',
  'Start today’s workout': 'شروع تمرین امروز',
  'Starts what’s planned for today, or opens the one already running.': 'برنامه امروز را شروع می‌کند، یا تمرینی را که در حال اجراست باز می‌کند.',
  'Stick it on the machine. Tap it during a workout to jump to {0}, or to add it.': 'آن را روی دستگاه بچسبانید. وسط تمرین با گوشی به آن بزنید تا به {0} بروید، یا اضافه‌اش کنید.',
  'Sticker ready.': 'برچسب آماده است.',
  'Sticker ready. Tap it with your phone to try it.': 'برچسب آماده است. با گوشی به آن بزنید تا امتحانش کنید.',
  'Tap it at the gym to start your workout or show your code.': 'در باشگاه با گوشی به آن بزنید تا تمرینتان شروع شود یا کدتان نمایش داده شود.',
  'That didn’t work. Hold your phone still on the sticker and try again.': 'نشد. گوشی را روی برچسب ثابت نگه دارید و دوباره امتحان کنید.',
  'This sticker can’t hold a link. Try an NTAG sticker.': 'این برچسب نمی‌تواند لینک نگه دارد. یک برچسب NTAG امتحان کنید.',
  'This sticker is for an exercise you don’t have.': 'این برچسب برای تمرینی است که ندارید.',
  'This sticker is locked. Try a blank one.': 'این برچسب قفل است. یک برچسب خالی امتحان کنید.',
  'This sticker is too small. NTAG213 or bigger works.': 'این برچسب خیلی کوچک است. NTAG213 یا بزرگ‌تر کار می‌کند.',
  'When you tap it': 'وقتی به آن می‌زنید',
  'Which code': 'کدام کد',
  'Write NFC sticker for this exercise': 'نوشتن برچسب NFC برای این تمرین',
  'Write sticker': 'نوشتن برچسب',
  'openGym isn’t allowed to use NFC here.': 'openGym اینجا اجازه استفاده از NFC را ندارد.',
  '“{0}” added': '«{0}» اضافه شد',
  'And beside it': 'و کنارش',
  'Best: {0}': 'بهترین: {0}',
  'Every badge collected. Legend.': 'همه نشان‌ها جمع شد. اسطوره‌اید.',
  'Freezes full. A missed week uses one, no harm done.': 'یخ‌زدگی‌ها پر است. یک هفته جاافتاده یکی را مصرف می‌کند، اتفاقی نمی‌افتد.',
  'Goal reached': 'به هدف رسیدید',
  'Last week: {0}': 'هفته گذشته: {0}',
  'Next badge at {0} weeks.': 'نشان بعدی در {0} هفته.',
