  'No goal set': 'هدفی تعیین نشده',
  'No weigh-ins yet': 'هنوز وزن‌کشی‌ای نیست',
  'Nothing planned': 'برنامه‌ای نیست',
  'Streak badges': 'نشان‌های هفته‌های پیاپی',
  'Streak freezes': 'یخ‌زدگی‌های زنجیره',
  'Streak freezes: {0} of {1}': 'یخ‌زدگی‌های زنجیره: {0} از {1}',
  'Week done. The flame lives on.': 'هفته تمام شد. شعله روشن می‌ماند.',
