  'What to show': 'چه چیزی نمایش داده شود',
  '{0} vs last week': '{0} نسبت به هفته قبل',
  '{0} weeks in a row. New badge!': '{0} هفته پیاپی. نشان جدید!',
  '{0} weeks: not yet': '{0} هفته: هنوز نه',
  '{0} weeks: reached': '{0} هفته: رسیدید',
  '{0} PR this month': '{0} رکورد شخصی این ماه',
  '{0} PRs this month': '{0} رکورد شخصی این ماه',
  'One more week with a workout earns a freeze.': 'یک هفته دیگر با تمرین، یک یخ‌زدگی به شما می‌دهد.',
  '{0} more weeks with a workout earn a freeze.': '{0} هفته دیگر با تمرین، یک یخ‌زدگی به شما می‌دهد.',
  'Watch on YouTube': 'تماشا در YouTube',
  'Opens a search for good form': 'جستجویی برای فرم درست باز می‌کند',
  'Share with a friend': 'اشتراک با یک دوست',
  'As a routine they can do too': 'به صورت روتینی که او هم بتواند انجام دهد',
  'Nothing to share in this one.': 'در این یکی چیزی برای اشتراک‌گذاری نیست.',
  'Link copied. Paste it to a friend.': 'لینک کپی شد. برای یک دوست بچسبانید.',
  'That one’s too big for a link, so it goes as a plan file.': 'این یکی برای لینک خیلی بزرگ است، پس به صورت فایل برنامه فرستاده می‌شود.',
  'Here’s my {0} on openGym 💪': 'این {0} من در openGym است 💪',
  'Couldn’t make a link for this one.': 'نتوانستیم برای این یکی لینک بسازیم.',
  'A link to “{0}”. Your friend taps it and adds it to their own openGym. The routine rides inside the link, no server in between.': 'لینکی به «{0}». دوستتان رویش می‌زند و آن را به openGym خودش اضافه می‌کند. روتین داخل خود لینک است، هیچ سروری وسط نیست.',
  'Include my weights': 'وزنه‌های من هم باشد',
  'Off: just sets, reps and rest. They pick their own weights.': 'خاموش: فقط ست، تکرار و استراحت. وزنه‌ها را خودشان انتخاب می‌کنند.',
  'So they know who it’s from.': 'تا بدانند از طرف کیست.',
  'Share link': 'اشتراک‌گذاری لینک',
  'From {0}': 'از طرف {0}',
  'Added as a new routine. Nothing you already have is touched.': 'به عنوان یک روتین جدید اضافه شد. به چیزهایی که از قبل دارید دست زده نمی‌شود.',
  'Add to my routines': 'افزودن به روتین‌های من',
  'Added to your routines': 'به روتین‌هایتان اضافه شد',
  'This link is from a newer openGym. Update the app to open it.': 'این لینک از نسخه جدیدتر openGym است. برای باز کردنش برنامه را به‌روز کنید.',
  'This browser can’t open this link. Try it in the openGym app.': 'این مرورگر نمی‌تواند این لینک را باز کند. در برنامه openGym امتحانش کنید.',
  'Nothing in this routine works here, sorry.': 'متأسفیم، هیچ چیز این روتین اینجا کار نمی‌کند.',
  'This routine link is broken or cut off.': 'لینک این روتین خراب یا ناقص است.',
  '(from {0})': '(از طرف {0})',
  'Mostly in the morning. The early bird gets the barbell.': 'بیشتر صبح‌ها. سحرخیز باش تا هالتر مال تو باشد.',
  'Mostly around lunch. Who needs a lunch break anyway?': 'بیشتر حوالی ناهار. اصلاً کی به استراحت ناهار نیاز دارد؟',
  'Mostly in the afternoon. The sweet spot.': 'بیشتر بعدازظهرها. بهترین زمان.',
  'Mostly in the evening. Work, then work out.': 'بیشتر عصرها. اول کار، بعد ورزش.',
  'Mostly late at night. The gym is all yours.': 'بیشتر آخر شب. باشگاه کاملاً مال شماست.',
  'Early bird': 'سحرخیز',
  'Most of your sessions started before 9. The sun was still catching up.': 'بیشتر جلسه‌هایتان قبل از ساعت ۹ شروع شد. خورشید هنوز داشت خودش را می‌رساند.',
  'Night owl': 'شب‌زنده‌دار',
  'Most of your sessions started after 8 pm. The quiet gym is your gym.': 'بیشتر جلسه‌هایتان بعد از ساعت ۸ شب شروع شد. باشگاه خلوت، باشگاه شماست.',
  'Leg-day loyalist': 'وفادار روز پا',
  'You never skipped leg day. Stairs fear you.': 'هیچ‌وقت روز پا را جا نینداختید. پله‌ها از شما می‌ترسند.',
  'Clockwork': 'مثل ساعت',
  'Week after week after week. Your calendar knows your name.': 'هفته پشت هفته پشت هفته. تقویمتان اسم شما را می‌شناسد.',
  'Record breaker': 'رکوردشکن',
  'So many new bests, your trophy shelf needs a trophy shelf.': 'آن‌قدر رکورد جدید زدید که قفسه جام‌هایتان خودش یک قفسه جام لازم دارد.',
  'Weekend warrior': 'جنگجوی آخر هفته',
  'Saturdays and Sundays are for lifting. Brunch can wait.': 'شنبه و یکشنبه برای وزنه زدن است. صبحانه دیرهنگام می‌تواند صبر کند.',
  'Cardio comet': 'شهاب کاردیو',
