  'Freestyle repeats what you did last time, with no progression rule. Rules apply to exercises in a routine.': 'تمرین آزاد همان کاری را تکرار می‌کند که دفعه قبل انجام دادید، بدون قاعده پیشرفت. قاعده‌ها برای تمرین‌های داخل یک روتین اعمال می‌شوند.',
  'Your watch thought this workout was forgotten. It keeps going here.': 'ساعت شما فکر کرد این تمرین فراموش شده. اینجا ادامه پیدا می‌کند.',
  'No rule (freestyle)': 'بدون قاعده (تمرین آزاد)',
  'Freestyle keeps the numbers you set. A rule picked here applies to this workout only.': 'تمرین آزاد اعدادی را که تعیین کرده‌اید نگه می‌دارد. قاعده‌ای که اینجا انتخاب شود فقط برای همین تمرین اعمال می‌شود.',
  'A number of ramp sets': 'چند ست افزایشی',
  'Add a warm-up': 'افزودن گرم‌کردن',
