  'Bar': 'میله',
  'Body': 'بدن',
  'Built from your work weight and rounded to this gym’s plates and dumbbells. An exercise can pick its own in its settings.': 'بر اساس وزنه اصلی شما ساخته می‌شود و به صفحه‌ها و دمبل‌های این باشگاه گرد می‌شود. هر تمرین می‌تواند در تنظیمات خودش گزینه خودش را داشته باشد.',
  'Built from your work weight when the workout starts.': 'هنگام شروع تمرین بر اساس وزنه اصلی شما ساخته می‌شود.',
