  'Each one closes half the gap to the work weight.': 'هر کدام نصف فاصله تا وزنه اصلی را پر می‌کند.',
  'Every loaded lift': 'هر حرکت با وزنه',
  'Feeling great': 'حالم عالی است',
  'Follows Settings → Workout → Automatic warm-ups.': 'از تنظیمات ← تمرین ← گرم‌کردن خودکار پیروی می‌کند.',
  'For this workout': 'برای این تمرین',
  'Heavy lifts get more rungs, light ones one or none.': 'حرکات سنگین پله‌های بیشتری می‌گیرند، حرکات سبک یکی یا هیچ.',
  'It hurts': 'درد دارد',
  'It hurts, it’s taken, no time, feeling great': 'درد دارد، دستگاه پر است، وقت ندارم، حالم عالی است',
  'It pinches, so lighter for the rest of it. Stop if it still hurts.': 'درد می‌گیرد، پس بقیه‌اش سبک‌تر. اگر هنوز درد دارد، متوقف شوید.',
  'It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.': 'درد می‌گیرد، پس ست‌های باقی‌مانده به حرکتی می‌روند که همان عضله را از زاویه ملایم‌تری درگیر می‌کند.',
  'Keep these warm-ups': 'این گرم‌کردن‌ها بمانند',
  'Kept. Same warm-ups next time, scaled to your work weight.': 'نگه داشته شد. دفعه بعد همین گرم‌کردن‌ها، متناسب با وزنه اصلی شما.',
  'Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': 'ست‌های ثبت‌شده و روتین شما همان‌طور می‌مانند. مربی پزشک یا فیزیوتراپ نیست. اگر جایی درد می‌کند، از یک متخصص بپرسید.',
  'Looking at your workout…': 'در حال بررسی تمرین شما…',
  'Machine’s taken': 'دستگاه پر است',
  'My own': 'مال خودم',
  'New programme “{0}”': 'دوره تمرینی جدید «{0}»',
  'Nothing at {0} {1}: that one starts cold.': 'در {0} {1} چیزی نیست: آن یکی بدون گرم‌کردن شروع می‌شود.',
  'Nothing could be applied any more.': 'دیگر چیزی قابل اعمال نبود.',
  'Nothing to change. Carry on as planned.': 'چیزی برای تغییر نیست. طبق برنامه ادامه دهید.',
  'One set less keeps the session doable today and still counts.': 'یک ست کمتر، جلسه امروز را شدنی نگه می‌دارد و باز هم حساب می‌شود.',
  'Only the warm-ups you plan yourself.': 'فقط گرم‌کردن‌هایی که خودتان برنامه‌ریزی می‌کنید.',
  'Ramped from the work weight: more rungs when it is heavy, fewer when it is light.': 'به صورت افزایشی از وزنه اصلی: وقتی سنگین است پله‌های بیشتر، وقتی سبک است کمتر.',
  'Remove warm-up {0}': 'حذف گرم‌کردن {0}',
  'Revise programme “{0}”': 'بازنگری دوره تمرینی «{0}»',
  'Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.': 'روتین‌ها، تمرین‌ها، ست‌ها و تکرارها، گرم‌کردن‌ها، دوره‌های تمرینی، زمان‌بندی هفتگی، تنظیمات پیشرفت و وزنه‌هایی که باشگاهتان دارد.',
  'Running on empty': 'باتری خالی',
  'Saved in the routine, scaled to your work weight': 'در روتین ذخیره شده، متناسب با وزنه اصلی شما',
  'Saved under Plan → Programmes. It starts when you start it.': 'در برنامه ← دوره‌های تمرینی ذخیره شد. وقتی شروعش کنید شروع می‌شود.',
  'Short on time': 'وقت کم دارم',
  'Skip the rest of {0}': 'رد کردن باقی {0}',
  'Something else': 'چیز دیگری',
  'Squats, presses, rows and friends get a ramp. Curls and raises start cold.': 'اسکوات، پرس، زیربغل و رفقا گرم‌کردن افزایشی می‌گیرند. جلوبازو و نشر بدون گرم‌کردن شروع می‌شوند.',
  'Straight into the work sets.': 'مستقیم سراغ ست‌های اصلی.',
  'That workout is over, so these can’t be applied any more.': 'آن تمرین تمام شده، پس این‌ها دیگر قابل اعمال نیستند.',
  'The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.': 'برنامه از وزنه اصلی شما به صورت افزایشی بالا می‌رود: وقتی سنگین است ست‌های گرم‌کردن بیشتر، وقتی سبک است کمتر، با صفحه‌های باشگاه شما.',
  'The rack is taken, so do it at the end. The rest of the session does not need it.': 'رک پر است، پس آن را آخر انجام دهید. بقیه جلسه به آن نیازی ندارد.',
  'There’s no workout running.': 'هیچ تمرینی در حال اجرا نیست.',
  'These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.': 'این گرم‌کردن‌ها در هر جلسه قبل از ست‌های اصلی می‌آیند، به صورت درصدی از وزنه اصلی، پس همراه آن بزرگ می‌شوند.',
  'This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.': 'این نسخه نمایشی است، پس هیچ مدل هوش مصنوعی پشت من نیست. روی سرور خودتان، جلسه شما را می‌خوانم و تغییراتی مثل این‌ها پیشنهاد می‌کنم.',
  'Warm-up {0}': 'گرم‌کردن {0}',
  'Warm-ups': 'گرم‌کردن‌ها',
  'What’s up? The Coach suggests a few changes to what is left of this workout. Logged sets stay as they are.': 'چه خبر؟ مربی چند تغییر برای باقی‌مانده این تمرین پیشنهاد می‌کند. ست‌های ثبت‌شده همان‌طور می‌مانند.',
  'Where, and what movement hurts? (optional)': 'کجا، و کدام حرکت درد دارد؟ (اختیاری)',
  'With {0} {1} today: {2}': 'با {0} {1} امروز: {2}',
