  'Wear OS watches talk to the phone through Google Play services, which F-Droid apps leave out. The APK from opengym.ch and the Google Play app have the watch link.': 'ساعت‌های Wear OS از طریق سرویس‌های Google Play با گوشی ارتباط می‌گیرند که برنامه‌های F-Droid آن را ندارند. APK از opengym.ch و برنامه Google Play اتصال ساعت را دارند.',
