  'Just training': 'فقط تمرین',
  'Log sets from your wrist on an Apple Watch, Wear OS or Zepp watch.': 'ست‌ها را از روی مچتان با Apple Watch، Wear OS یا ساعت Zepp ثبت کنید.',
  'Log, plan, progress. Nothing else on the screen.': 'ثبت، برنامه‌ریزی، پیشرفت. هیچ چیز دیگری روی صفحه نیست.',
  'Logging, plans, history, the exercise library and the basic stats are always on.': 'ثبت، برنامه‌ها، تاریخچه، کتابخانه تمرینات و آمار پایه همیشه روشن‌اند.',
  'Modules': 'ماژول‌ها',
  'Motivation': 'انگیزه',
  'Plates and warm-ups': 'صفحه‌ها و گرم‌کردن',
  'Plus weigh-ins, measurements, photos and your health apps.': 'به علاوه وزن‌کشی‌ها، اندازه‌گیری‌ها، عکس‌ها و برنامه‌های سلامت شما.',
  'Rate each set in RIR or RPE, and see in Stats how hard you really push.': 'به هر ست با RIR یا RPE نمره بدهید، و در آمار ببینید واقعاً چقدر به خودتان فشار می‌آورید.',
  'Reviews your training and suggests changes. You still say yes or no.': 'تمرینات شما را بازبینی می‌کند و تغییر پیشنهاد می‌دهد. تصمیم بله یا نه همچنان با شماست.',
  'Scheduled Coach reviews take a break while the AI Coach is off. Your setup and chats stay.': 'وقتی مربی هوش مصنوعی خاموش است، بازبینی‌های زمان‌بندی‌شده مربی استراحت می‌کنند. تنظیمات و گفتگوهایتان می‌مانند.',
  'Start from': 'شروع از',
  'Streaks, challenges, badges, recaps and your year in openGym.': 'هفته‌های پیاپی، چالش‌ها، نشان‌ها، مرورها و سال شما در openGym.',
  'Streaks, the Coach, themes, the lot.': 'هفته‌های پیاپی، مربی، پوسته‌ها، همه چیز.',
  'Switch off': 'خاموش کردن',
  'Switch off what you don’t use. Nothing gets deleted: switch it back on and it’s all still there.': 'چیزهایی را که استفاده نمی‌کنید خاموش کنید. چیزی حذف نمی‌شود: دوباره روشنش کنید و همه چیز سر جایش است.',
  'Switch off {0}?': '{0} خاموش شود؟',
  'Switch these off?': 'این‌ها خاموش شوند؟',
  'The plates to load under every set, and warm-ups that build themselves.': 'صفحه‌هایی که برای هر ست باید روی میله بگذارید، و گرم‌کردن‌هایی که خودشان ساخته می‌شوند.',
  'Training': 'تمرین',
  'Training and body': 'تمرین و بدن',
  'Watch': 'ساعت',
  'Webhooks for Home Assistant and friends, and the MCP server.': 'وب‌هوک‌ها برای Home Assistant و رفقا، و سرور MCP.',
  'Weigh-ins, measurements, progress photos and your weight goal.': 'وزن‌کشی‌ها، اندازه‌گیری‌ها، عکس‌های پیشرفت و هدف وزنی شما.',
  'Your membership codes on Home, and NFC stickers that start a workout.': 'کدهای عضویت شما در صفحه خانه، و برچسب‌های NFC که تمرین را شروع می‌کنند.',
  'Your own mix. Flip the switches below.': 'ترکیب خودتان. کلیدهای پایین را بزنید.',
  'Your watch stops getting workouts while Watch is off. It stays paired.': 'تا وقتی «ساعت» خاموش است، ساعت شما تمرینی دریافت نمی‌کند. جفت‌شده باقی می‌ماند.',
  'Your webhooks stop sending while Integrations is off. They stay set up.': 'تا وقتی «یکپارچه‌سازی‌ها» خاموش است، وب‌هوک‌هایتان چیزی نمی‌فرستند. تنظیماتشان می‌ماند.',
  '{0} of {1} modules on.': '{0} از {1} ماژول روشن است.',
  '{0} stops syncing while Health is off. Nothing is disconnected, and it catches up once Health is back.': 'تا وقتی «سلامت» خاموش است، {0} همگام‌سازی نمی‌شود. اتصالی قطع نمی‌شود و وقتی «سلامت» برگردد، عقب‌افتادگی جبران می‌شود.',
  'Weight step': 'گام وزنه',
