  'Use {0} for every exercise?': '{0} برای همه تمرین‌ها استفاده شود؟',
  '{0} exercise in your routines changes to it. You can still give any of them its own step later.': '{0} تمرین در روتین‌هایتان به آن تغییر می‌کند. بعداً هم می‌توانید به هر کدام گام مخصوص خودش را بدهید.',
  '{0} exercises in your routines change to it. You can still give any of them its own step later.': '{0} تمرین در روتین‌هایتان به آن تغییر می‌کنند. بعداً هم می‌توانید به هر کدام گام مخصوص خودش را بدهید.',
  'Apply to all': 'اعمال برای همه',
