  "Open this day": "باز کردن این روز",
  "Planned, not trained. Any other day this week still counts.": "برنامه‌ریزی شده، تمرین نشد. هر روز دیگر این هفته هنوز حساب می‌شود.",
  "Planned, not trained. Any workout that week would have counted.": "برنامه‌ریزی شده، تمرین نشد. هر تمرینی در آن هفته حساب می‌شد.",
  "Planned, not trained. No harm done: you trained another day that week, so it still counts.": "برنامه‌ریزی شده، تمرین نشد. اشکالی ندارد: روز دیگری تمرین کردی، پس آن هفته حساب می‌شود.",
  "Bank 1 freeze, earned every 4 trained weeks. Two missed weeks in a row end the streak.": "۱ یخ‌زدگی ذخیره، هر ۴ هفتهٔ تمرین یکی. دو هفتهٔ پشت سر هم جا بیفتد، زنجیره تمام می‌شود.",
  "Bank up to 2 freezes, one every 4 trained weeks. Even two missed weeks in a row can be covered.": "تا ۲ یخ‌زدگی ذخیره، هر ۴ هفتهٔ تمرین یکی. حتی دو هفتهٔ پشت سر هم جاافتاده هم پوشش داده می‌شود.",
  "Change the freeze rule": "تغییر قاعدهٔ یخ‌زدگی",
  "Every 4th week you train earns a freeze. You can bank 1.": "هر چهارمین هفته‌ای که تمرین کنی یک یخ‌زدگی می‌گیری. ۱ تا می‌توانی نگه داری.",
  "Every week counts. Miss one and the streak starts over.": "هر هفته حساب است. یکی جا بیفتد، زنجیره از نو شروع می‌شود.",
  "From now on: {0}.": "از حالا: {0}.",
