  "Generous": "سخاوتمند",
  "Gentle": "ملایم",
  "How forgiving should your week streak be?": "زنجیرهٔ هفتگی‌ات چقدر بخشنده باشد؟",
  "How strict should your streak be?": "زنجیره‌ات چقدر سخت‌گیر باشد؟",
  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. Two missed weeks in a row, and it starts over.": "هفته‌ای را جا انداختی؟ یک یخ‌زدگی پوشش می‌دهد: زنجیره ادامه دارد، فقط آن هفته چیزی اضافه نمی‌کند. دو هفتهٔ پشت سر هم، و از نو شروع می‌شود.",
  "No freezes": "بدون یخ‌زدگی",
  "No freezes on your rule. Every week counts.": "قاعدهٔ تو یخ‌زدگی ندارد. هر هفته حساب است.",
  "No freezes on your rule: a week without a workout starts it over.": "قاعدهٔ تو یخ‌زدگی ندارد: یک هفته بی‌تمرین و زنجیره از نو شروع می‌شود.",
  "No workout, and your rule has no freezes, so the streak started over.": "تمرینی نبود و قاعدهٔ تو یخ‌زدگی ندارد، پس زنجیره از نو شروع شد.",
  "Weeks already counted stay as they are.": "هفته‌هایی که حساب شده‌اند همان‌طور می‌مانند.",
  "You can change it later in Settings. A change counts from then on.": "بعداً در تنظیمات می‌توانی عوضش کنی. تغییر از همان موقع حساب می‌شود.",
  "Your rule right now: {0}.": "قاعدهٔ فعلی‌ات: {0}.",
  "Your streak counts weeks with at least one workout. Freezes can cover the odd missed week.": "زنجیره‌ات هفته‌هایی با دست‌کم یک تمرین را می‌شمارد. یخ‌زدگی می‌تواند گاهی یک هفتهٔ جاافتاده را بپوشاند.",
