  "{0} sees only what is on here.": "{0} فقط آنچه را اینجا روشن است می‌بیند.",
  "You are letting this trainer see the categories marked here, and change the ones marked suggest or apply. If the trainer works for a gym, its gym lead sees the categories in the gym lead row, never more than view. You can change this or disconnect any time, and it stops working the moment you do. Every look and every change is written to your sharing log, which only you can read.": "تو به این ترینر اجازه می‌دهی دسته‌های علامت‌خورده در اینجا را ببیند و دسته‌هایی را که پیشنهاد یا تغییر مستقیم علامت خورده‌اند تغییر دهد. اگر ترینر برای یک باشگاه کار می‌کند، مدیر آن باشگاه دسته‌های ردیف مدیر باشگاه را می‌بیند و هرگز بیشتر از مشاهده نه. هر وقت خواستی می‌توانی این را تغییر دهی یا ارتباط را قطع کنی و همان لحظه از کار می‌افتد. هر مشاهده و هر تغییر در گزارش اشتراک‌گذاری تو نوشته می‌شود که فقط خودت می‌توانی بخوانی.",
  "A change": "یک تغییر",
