  "That tip did not come through.": "آن نکته نرسید.",
  "The sharing text changed. Have a quick read and try again.": "متن اشتراک‌گذاری عوض شده. سریع یک نگاه بینداز و دوباره امتحان کن.",
  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "این برای همه در این سرور عمومی است: هر کسی که اینجا حساب دارد می‌تواند ببیندش، امتحانش کند و از آن کپی بگیرد. اسمت و تاریخ همیشه همراهش هستند. فقط چیزی را به اشتراک بگذار که مال خودت است: چیزی که خودت ساخته‌ای، ضبط کرده‌ای یا حق داری به دیگران بدهی. تصویرها و انیمیشن‌های تمرین در کتابخانهٔ داخلی مجوز دارند و هیچ‌وقت نمی‌شود آن‌ها را به اشتراک گذاشت. هر وقت بخواهی می‌توانی اشتراک‌گذاری را متوقف کنی؛ نسخه‌هایی که دیگران برداشته‌اند پیش خودشان می‌ماند.",
  "This kind of item cannot be taken.": "این نوع مورد را نمی‌شود برداشت.",
