  "Link your {0} account and sign in with it from now on. Your passkeys keep working too. First a quick check that this is really you.": "حساب {0} خود را پیوند دهید و از این پس با آن وارد شوید. کلیدهای عبورتان هم کار می‌کنند. اول یک بررسی سریع که واقعاً خودتان هستید.",
  "Linked. You can sign in with {0} from now on.": "پیوند شد. از این پس می‌توانید با {0} وارد شوید.",
  "Linked. {0} signs you in here.": "پیوند شده. {0} شما را اینجا وارد می‌کند.",
  "Not linked yet.": "هنوز پیوند نشده.",
  "Off to {0}…": "در راه {0}…",
  "Sign in with your provider again first, then try once more.": "اول دوباره نزد ارائه‌دهنده‌تان وارد شوید، بعد یک بار دیگر امتحان کنید.",
  "Sign in with {0}": "ورود با {0}",
  "Sign-in cancelled. No harm done.": "ورود لغو شد. مشکلی پیش نیامد.",
  "That sign-in took too long or came from another tab. Give it another go.": "این ورود خیلی طول کشید یا از زبانهٔ دیگری آمد. دوباره امتحان کنید.",
  "That was a different {0} account than the one linked to this profile.": "این حساب {0} دیگری بود، نه همانی که به این نمایه پیوند دارد.",
  "That {0} account is already linked to another profile here.": "این حساب {0} اینجا به نمایهٔ دیگری پیوند دارد.",
  "This profile is already linked to a {0} account.": "این نمایه از قبل به یک حساب {0} پیوند دارد.",
  "This profile is linked to your {0} account, so signing in there signs you in here.": "این نمایه به حساب {0} شما پیوند دارد: آنجا وارد باشید، اینجا هم وارد هستید.",
  "This server is invite-only and {0} alone does not get you in. Ask whoever runs it.": "این سرور فقط با دعوت است و {0} به‌تنهایی کافی نیست. از گردانندهٔ آن بپرسید.",
  "This server signs everyone in with {0}. New here? Signing in makes your profile.": "در این سرور همه با {0} وارد می‌شوند. تازه‌وارد هستید؟ با ورود، نمایهٔ شما ساخته می‌شود.",
  "This server signs people in with {0}.": "این سرور افراد را با {0} وارد می‌کند.",
  "Too many attempts. Try again in a minute.": "تلاش‌ها خیلی زیاد بود. یک دقیقه دیگر دوباره امتحان کنید.",
  "Unlink": "لغو پیوند",
  "Unlinked. {0} no longer signs you in here.": "پیوند لغو شد. {0} دیگر شما را اینجا وارد نمی‌کند.",
  "or use a pairing code": "یا از کد اتصال استفاده کنید",
  "{0} could not be reached. Try again in a moment.": "دسترسی به {0} ممکن نشد. کمی بعد دوباره امتحان کنید.",
  "{0} is the only way into this profile, so it stays linked. Add a passkey first.": "{0} تنها راه ورود به این نمایه است، پس پیوند می‌ماند. اول یک کلید عبور اضافه کنید.",
  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "{0} اجازهٔ ورود داد، اما این سرور فقط گروه‌های مشخصی را می‌پذیرد. از گردانندهٔ آن بخواهید شما را اضافه کند.",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "{0} چیزی برگرداند که نتوانستیم تأییدش کنیم، پس کسی وارد نشد. اگر تکرار شد، صفحهٔ مدیریت دلیلش را نشان می‌دهد.",
  "Backups: {0}": "جایگزین‌ها: {0}",
