  "For machines and cables that feel different from gym to gym. Free weights rarely need it.": "برای دستگاه‌ها و سیم‌کش‌هایی که در هر باشگاه حس متفاوتی دارند. وزنه‌های آزاد به‌ندرت لازمش دارند.",
  "All gyms": "همهٔ باشگاه‌ها",
