  "Strava uploads come from your own openGym server, so they need one. Connect this device to it in Account.": "بارگذاری‌های Strava از سرور openGym خودتان انجام می‌شود، پس یکی لازم دارید. این دستگاه را در حساب به آن وصل کنید.",
