  "Subscribe to this link in your calendar app. Anyone with it sees your plan, so keep it to yourself.": "در برنامهٔ تقویمتان مشترک این پیوند شوید. هر کس آن را داشته باشد برنامه‌تان را می‌بیند، پس پیش خودتان نگهش دارید.",
