  "The calendar link is served by your own openGym server, so it needs one. Connect this device to it in Account.": "پیوند تقویم را سرور openGym خودتان ارائه می‌دهد، پس یکی لازم دارید. این دستگاه را در حساب به آن وصل کنید.",
  "The link stops working at once. What your calendar already shows may stay until it refreshes.": "پیوند فوراً از کار می‌افتد. چیزی که تقویمتان الان نشان می‌دهد ممکن است تا به‌روزرسانی بعدی بماند.",
  "The old link stops working, and every calendar that uses it needs the new one.": "پیوند قبلی از کار می‌افتد و هر تقویمی که از آن استفاده می‌کند پیوند جدید را لازم دارد.",
  "The password stays on this device, in its secure storage. It is never synced or put in a backup.": "رمز عبور روی همین دستگاه، در فضای امنش می‌ماند. هرگز همگام‌سازی نمی‌شود و در پشتیبان هم نمی‌رود.",
  "The server cannot show this link again. Make a new one.": "سرور نمی‌تواند این پیوند را دوباره نشان دهد. یکی جدید بسازید.",
  "This device stops backing up and forgets the password. The backups already in the folder stay there.": "این دستگاه دیگر پشتیبان نمی‌گیرد و رمز عبور را فراموش می‌کند. پشتیبان‌هایی که در پوشه هستند همان‌جا می‌مانند.",
