  // --- Settings → Garmin (garmin-146) ---
  "This version of openGym comes without the Garmin link, since Garmin’s part of it isn’t open source. The App Store, Google Play and GitHub versions have it.": "این نسخه از openGym اتصال Garmin ندارد، چون بخش Garmin متن‌باز نیست. نسخه‌های App Store، Google Play و GitHub آن را دارند.",
  "Garmin Connect isn’t on this phone. Install it, pair your watch there, then come back here.": "Garmin Connect روی این گوشی نیست. نصبش کن، ساعتت را آنجا جفت کن و بعد به اینجا برگرد.",
  "Garmin Connect needs an update before openGym can talk to your watch.": "Garmin Connect پیش از آنکه openGym بتواند با ساعتت حرف بزند، به‌روزرسانی لازم دارد.",
  "Couldn’t reach Garmin Connect. Try again in a moment.": "به Garmin Connect دسترسی پیدا نشد. کمی بعد دوباره امتحان کن.",
  "Pick your Garmin in Garmin Connect and your workouts show up on your wrist.": "Garmin خودت را در Garmin Connect انتخاب کن تا تمرین‌هایت روی مچت بیاید.",
  "Garmin Connect doesn’t know a watch yet. Pair yours there first.": "Garmin Connect هنوز هیچ ساعتی را نمی‌شناسد. اول ساعتت را آنجا جفت کن.",
  "openGym is on your Garmin. Sets you log on the wrist land here.": "openGym روی Garmin توست. ست‌هایی که روی مچ ثبت می‌کنی به اینجا می‌رسند.",
  "openGym is on your Garmin. It catches up as soon as the watch is in reach.": "openGym روی Garmin توست. همین که ساعت در دسترس باشد همه چیز را می‌گیرد.",
  "Your Garmin is here, openGym isn’t on it yet. Get it, then open it once on the watch.": "Garmin تو اینجاست، ولی openGym هنوز رویش نیست. نصبش کن و یک بار روی ساعت بازش کن.",
  "Not in reach": "خارج از دسترس",
