  "Nothing logged for a while. If you’re done, it ends by itself at {0}, saved at your last set.": "مدتی است چیزی ثبت نشده. اگر تمام شد، در {0} خودش تمام می‌شود و با آخرین ست ذخیره می‌شود.",
  "Forgotten workouts": "تمرین‌های فراموش‌شده",
  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "اگر کسی جواب ندهد، خودش تمام می‌شود و هیچ‌وقت چیزی را دور نمی‌ریزد. پایان، آخرین ستت به‌اضافهٔ استراحتش است تا زمان صادق بماند. تا یک روز می‌توانی از تاریخچه دوباره بازش کنی. ساعتت هم می‌پرسد.",
  "Never asks and never ends one by itself.": "هیچ‌وقت نمی‌پرسد و هیچ‌وقت خودش چیزی را تمام نمی‌کند.",
